const lv_img_dsc_t *arrow_for_direction(uint8_t direction, bool small)
{
    const lv_img_dsc_t *const *table = small ? direction_small : direction_big;
    if (direction >= sizeof(direction_big) / sizeof(direction_big[0])) {
        return NULL;
    }
    return table[direction];
}
